#!/bin/sh
# Rebuilds the generated files of the system map: objects/_index.md, processes/_index.md and
# the AGENTS.md / routing.md twins of the entry files. Run it with `task map` after adding,
# renaming or re-verifying a card. Never edit the generated files by hand.
set -eu
map=$(cd "$(dirname "$0")/.." && pwd)
root=$(cd "$map/../.." && pwd)

# card_line FILE LINK: "- [Title](LINK) — first sentence · status" (universe shown unless live)
card_line() {
	awk -v link="$2" '
		NR == 1 && $0 == "---" { fm = 1; next }
		fm && $0 == "---" { fm = 0; next }
		fm && /^status:/ { status = $2 }
		fm && /^universe:/ { universe = $2 }
		fm { next }
		/^# / && title == "" { title = substr($0, 3); next }
		title != "" && summary == "" && NF > 0 { summary = $0 }
		END {
			# links in a card are relative to its own folder: keep their text only
			while (match(summary, /\[[^]]*\]\([^)]*\)/)) {
				seg = substr(summary, RSTART, RLENGTH)
				summary = substr(summary, 1, RSTART - 1) substr(seg, 2, index(seg, "](") - 2) substr(summary, RSTART + RLENGTH)
			}
			tag = status
			if (universe != "" && universe != "live") tag = tag ", " universe
			printf "- [%s](%s) — %s · %s\n", title, link, summary, tag
		}
	' "$1"
}

{
	echo "# Objects index"
	echo
	echo "Generated by \`task map\` from the cards' frontmatter and first sentence. Do not edit."
	for cluster in sources valuation views ledger storage web; do
		echo
		echo "## $cluster"
		echo
		for f in "$map/objects/$cluster"/*.md; do
			[ -e "$f" ] || continue
			card_line "$f" "$cluster/$(basename "$f")"
		done
	done
} > "$map/objects/_index.md"

{
	echo "# Processes index"
	echo
	echo "Generated by \`task map\` from the cards' frontmatter and first sentence. Do not edit."
	echo
	for f in "$map/processes"/*.md; do
		case $(basename "$f") in _index.md | CONTEXT.md) continue ;; esac
		card_line "$f" "$(basename "$f")"
	done
} > "$map/processes/_index.md"

cp "$map/CLAUDE.md" "$map/AGENTS.md"
cp "$map/CLAUDE.md" "$map/routing.md"
cp "$root/CLAUDE.md" "$root/AGENTS.md"
echo "map: rebuilt indexes and entry-file twins"
